/* ==================== المالية: الشجرة + السندات + الشيكات + الحسابات البنكية (5.2.0) ==================== */
const FIN_TREE=[
  {k:'main',ic:'🗄️',l:'الخزينة الرئيسية',sub:'سند قبض · سند صرف · تحويلات',tabs:[['overview','📊 نظرة عامة'],['rv','⬇️ سند قبض'],['pv','⬆️ سند صرف'],['transfers','🔁 التحويلات'],['ledger','📒 دفتر الخزينة'],['closing','🔒 الإقفال والقفل'],['handover','🤝 تسليم وتسلم'],['insight','🎯 الميزانية والتنبيهات'],['report','📑 التقرير الشهري والمواقف'],['consolidated','🧾 التقرير الشامل']]},
  {k:'sub',ic:'🧰',l:'الخزينة الفرعية',sub:'صندوق العُهد والسلف · يتغذّى من الرئيسية',tabs:[['subledger','📒 حركة الصندوق الفرعي'],['advances','📋 العُهد والسلف'],['custody','🧰 العُهد'],['loans','🤝 السلف'],['expenses','🧾 المصروفات']]},
  {k:'bank',ic:'🏦',l:'البنك',sub:'الحسابات · الشيكات · المطابقة',tabs:[['banks','🏦 الحسابات والحركات'],['cheques','🧾 الشيكات'],['recon','🔍 مطابقة البنك']]}];
let vFilter={q:'',from:'',to:'',acct:'',type:''},chqFilter={st:'open',kind:'',q:''},advKind='',bankSel='';
const REF_LBL={advance:'سلفة',custody:'عهدة',expense:'مصروف',repayment:'سداد',custody_return:'رد عهدة',reimburse:'رد مصروف',invoice:'فاتورة',payment:'راتب',reversal:'عكس',cheque:'شيك',transfer:'تحويل'};
const CHQ_ST={held:{l:'محفوظ',cls:'b-info'},deposited:{l:'مودع',cls:'b-primary'},deferred:{l:'مؤجل',cls:'b-warn'},cleared:{l:'محصّل / مصروف',cls:'b-ok'},bounced:{l:'مرتد',cls:'b-danger'},cancelled:{l:'ملغى',cls:'b-muted'}};
const CHQ_OPEN=['held','deposited','deferred'];
const finBranchOf=t=>{for(const b of FIN_TREE)if(b.tabs.some(x=>x[0]===t))return b.k;return 'main';};
function branchBalance(k){
  if(k==='main')return Object.keys(ACCOUNTS).filter(a=>!isBankKey(a)&&a!=='sub').reduce((s,a)=>s+treasuryBalance(null,a),0);
  if(k==='bank')return Object.keys(ACCOUNTS).filter(isBankKey).reduce((s,a)=>s+treasuryBalance(null,a),0);
  return treasuryBalance(null,'sub');}
const openCustodyTotal=()=>S.advances.filter(a=>a.kind==='custody'&&a.status==='disbursed').reduce((s,a)=>s+toAED(advRemaining(a),a.currency),0);
function renderFinance(){
  const br=finBranchOf(finTab),B=FIN_TREE.find(x=>x.k===br);
  const cards=FIN_TREE.map(b=>`<div class="tile ${b.k===br?'info':''}" style="cursor:pointer" onclick="finTab='${b.tabs[0][0]}';render()"><div class="lbl">${b.ic} ${b.l}${b.k===br?' ◂':''}</div><div class="num" style="font-size:1.45rem">${n2(branchBalance(b.k))} د.إ</div><div class="sub">${b.k==='sub'?`رصيد الصندوق · عُهد قائمة ${n0(openCustodyTotal())} د.إ`:b.sub}</div></div>`).join('');
  const V={overview:finOverview,ledger:finLedger,advances:()=>{advKind='';return finAdvances();},custody:()=>{advKind='custody';return finAdvances();},loans:()=>{advKind='loan';return finAdvances();},expenses:finExpenses,report:renderFinReport,handover:finHandover,insight:finInsight,recon:finRecon,closing:finClosing,rv:()=>finVouchers('in'),pv:()=>finVouchers('out'),transfers:finTransfers,banks:finBanks,cheques:finCheques,subledger:finSubLedger,consolidated:finConsolidated};
  return `<div class="grid g3" style="margin-bottom:12px">${cards}</div>
  <div class="card tight"><div class="tabs" style="margin:0;padding:0 14px">${B.tabs.map(([k,l])=>`<button class="tab ${finTab===k?'active':''}" onclick="finTab='${k}';render()">${l}</button>`).join('')}</div></div>
  ${(V[finTab]||finOverview)()}`;}

/* ---------- السندات (قبض / صرف) ---------- */
function vRows(dir){const f=vFilter,q=(f.q||'').toLowerCase();
  return S.treasury.filter(t=>t.direction===dir&&t.ref_type!=='transfer'&&(!f.from||t.date>=f.from)&&(!f.to||t.date<=f.to)&&(!f.acct||acctOf(t)===f.acct)&&(!f.type||t.category===f.type)&&(!q||[t.vno,t.party,t.category,t.note,t.extra,(empById(t.emp_id)||{}).name].join(' ').toLowerCase().includes(q))).sort((a,b)=>b.date.localeCompare(a.date)||(b.vno||'').localeCompare(a.vno||''));}
function partyOf(t){const e=empById(t.emp_id);return t.party||(e?e.name:'');}
function extraOf(t){if(!t.extra)return '';try{const o=JSON.parse(t.extra);return Object.entries(o).filter(([,v])=>v!==''&&v!=null).map(([k,v])=>`${k}: ${v}`).join(' · ');}catch{return '';}}
function finVouchers(dir){const rows=vRows(dir),isIn=dir==='in',tot=rows.reduce((s,t)=>s+trAmt(t),0);
  const types=[...new Set(S.treasury.filter(t=>t.direction===dir&&t.ref_type!=='transfer').map(t=>t.category).filter(Boolean))];
  return `<div class="card tight" style="margin-top:16px"><div class="card-head"><div class="toolbar"><input class="search" placeholder="🔍 رقم السند، الاسم، البيان…" value="${esc(vFilter.q)}" oninput="vFilter.q=this.value;render()">
  <label class="muted mini">من</label><input type="date" class="search" style="min-width:140px" value="${vFilter.from}" onchange="vFilter.from=this.value;render()"><label class="muted mini">إلى</label><input type="date" class="search" style="min-width:140px" value="${vFilter.to}" onchange="vFilter.to=this.value;render()">
  <select class="search" style="min-width:130px" onchange="vFilter.type=this.value;render()"><option value="">كل الأنواع</option>${types.map(c=>`<option ${vFilter.type===c?'selected':''}>${esc(c)}</option>`).join('')}</select>
  <select class="search" style="min-width:140px" onchange="vFilter.acct=this.value;render()"><option value="">كل الحسابات</option>${Object.keys(ACCOUNTS).map(k=>`<option value="${k}" ${vFilter.acct===k?'selected':''}>${esc(ACCOUNTS[k])}</option>`).join('')}</select></div>
  <div class="toolbar"><button class="btn" onclick="exportVouchers('${dir}')">⬇️ تصدير Excel</button><button class="btn" onclick="printVoucherReport('${dir}')">🖨️ تقرير</button><button class="btn" onclick="openVoucherFieldsEditor('${dir}')">⚙️ تخصيص السند</button><button class="btn primary" onclick="openTreasuryForm('${dir}')">＋ ${isIn?'سند قبض جديد':'سند صرف جديد'}</button></div></div>
  <div class="table-wrap">${rows.length?`<table><thead><tr><th>رقم السند</th><th>التاريخ</th><th>${isIn?'من':'إلى'}</th><th>النوع</th><th>الحساب</th><th>البيان</th><th class="num">المبلغ</th><th></th></tr></thead><tbody>${rows.map(t=>`<tr><td><b dir="ltr">${esc(t.vno||'—')}</b></td><td>${fmtDate(t.date)}</td><td>${partyOf(t)?`<b>${esc(partyOf(t))}</b>`:'<span class="muted">—</span>'}${projBadge(t.project_id)}</td><td><span class="badge ${isIn?'b-ok':'b-danger'}">${esc(t.category||'')}</span>${t.ref_type?` <span class="muted mini">(${REF_LBL[t.ref_type]||''})</span>`:''}</td><td class="mini">${esc(ACCT_SHORT[acctOf(t)]||'')}</td><td class="mini">${esc(t.note||'')}${extraOf(t)?`<div class="muted">${esc(extraOf(t))}</div>`:''}</td><td class="num" style="color:${isIn?'var(--ok)':'var(--neg)'}"><b>${money(t.amount,t.currency)}</b></td><td style="white-space:nowrap"><button class="btn sm" title="طباعة" onclick="printTreasuryVoucher('${t.id}')">🖨️</button> ${t.ref_type?'':`<button class="btn sm" title="تعديل" onclick="openTreasuryForm('${dir}','${t.id}')">✏️</button> `}<button class="btn sm" title="حذف" onclick="delTreasury('${t.id}')">✕</button></td></tr>`).join('')}</tbody><tfoot><tr><td colspan="6"><b>الإجمالي (${rows.length} سند)</b></td><td class="num"><b>${n2(tot)} د.إ</b></td><td></td></tr></tfoot></table>`:'<div class="empty">لا توجد سندات بهذه الشروط. اضغط «سند جديد» للبدء.</div>'}</div></div>
  <p class="muted mini" style="margin-top:8px">كل حركة تُسجَّل مرة واحدة هنا وتظهر تلقائياً في دفتر الخزينة والتقارير. سندات الرواتب والسلف والعُهد والشيكات تُنشأ تلقائياً من أقسامها وتظهر هنا برقمها.</p>`;}
function previewVno(dir,date){const pre=dir==='in'?'RV':'PV',y=(date||iso(today())).slice(0,4);let max=0;for(const t of S.treasury){const p=String(t.vno||'').split('-');if(p[0]===pre&&p[1]===y)max=Math.max(max,parseInt(p[2],10)||0);}return `${pre}-${y}-${String(max+1).padStart(4,'0')}`;}
function vfields(dir){const v=S.settings.voucherFields;return (v&&Array.isArray(v[dir]))?v[dir]:[];}
function openTreasuryForm(dir,id,projId){
  const ed=id?S.treasury.find(t=>t.id===id):null;const isIn=dir==='in';pendingFile=null;
  let ex={};if(ed&&ed.extra){try{ex=JSON.parse(ed.extra)||{};}catch{}}
  const parties=[...new Set(S.treasury.map(t=>t.party).filter(Boolean))];
  const cf=vfields(dir).map((f,i)=>{const val=ex[f.label]!=null?ex[f.label]:'';const idf='vf_'+i;
    const inp=f.type==='list'?`<select id="${idf}"><option value=""></option>${(f.opts||[]).map(o=>`<option ${val===o?'selected':''}>${esc(o)}</option>`).join('')}</select>`:`<input id="${idf}" type="${f.type==='number'?'number':f.type==='date'?'date':'text'}" ${f.type==='number'?'step="0.01" dir="ltr"':''} value="${esc(val)}">`;
    return `<div class="field"><label>${esc(f.label)} <span class="muted mini">(اختياري)</span></label>${inp}</div>`;}).join('');
  openModal(ed?(isIn?'✏️ تعديل سند قبض':'✏️ تعديل سند صرف'):(isIn?'سند قبض جديد':'سند صرف جديد'),
  `<div class="frow3"><div class="field"><label>رقم السند</label><input id="t_vno" value="${esc(ed?(ed.vno||''):'')}" placeholder="${esc(previewVno(dir))} (تلقائي)" disabled></div><div class="field"><label>التاريخ</label><input type="date" id="t_date" value="${ed?ed.date:iso(today())}"></div><div class="field"><label>${isIn?'الإيداع في':'الصرف من'}</label><select id="t_acct">${Object.keys(ACCOUNTS).map(k=>`<option value="${k}" ${(ed?acctOf(ed):'main')===k?'selected':''}>${esc(ACCOUNTS[k])}</option>`).join('')}</select></div></div>
  <div class="frow"><div class="field"><label>${isIn?'استلمنا من':'صُرف إلى'}</label><input id="t_party" list="t_parties" value="${esc(ed?(ed.party||''):'')}" placeholder="${isIn?'اسم العميل أو الجهة':'اسم المستلم أو الجهة'}"><datalist id="t_parties">${parties.map(p=>`<option value="${esc(p)}">`).join('')}</datalist></div><div class="field"><label>نوع السند</label>${selWithAdd('t_cat',isIn?'treasuryInCats':'treasuryOutCats',ed?ed.category:null)}</div></div>
  <div class="frow3"><div class="field"><label>المبلغ *</label><input type="number" step="0.01" id="t_amt" dir="ltr" value="${ed?ed.amount:''}"></div><div class="field"><label>العملة</label><select id="t_cur"><option ${ed&&ed.currency==='AED'?'selected':''}>AED</option><option ${ed&&ed.currency==='USD'?'selected':''}>USD</option></select></div><div class="field"><label>الموظف <span class="muted mini">(اختياري)</span></label><select id="t_emp"><option value="">—</option>${activeEmps().map(e=>`<option value="${e.id}" ${ed&&ed.emp_id===e.id?'selected':''}>${esc(e.name)}</option>`).join('')}</select></div></div>
  <div class="frow3"><div class="field"><label>طريقة ${isIn?'القبض':'الصرف'}</label><select id="t_method" onchange="document.getElementById('t_chqbox').classList.toggle('hidden',this.value!=='cheque')" ${ed?'disabled':''}><option value="cash" ${(ex['الطريقة']||'كاش')==='كاش'?'selected':''}>💵 كاش</option><option value="transfer" ${ex['الطريقة']==='تحويل بنكي'?'selected':''}>🏦 تحويل بنكي</option>${ed?'':'<option value="cheque">🧾 شيك</option>'}</select></div><div id="t_chqbox" class="frow hidden" style="grid-column:span 2"><div class="field"><label>رقم الشيك</label><input id="t_chqno" dir="ltr"></div><div class="field"><label>بنك الشيك / موعد الصرف</label><input id="t_chqbank" placeholder="اسم البنك"><input type="date" id="t_chqdue" style="margin-top:4px"></div></div></div>
  ${projField('t_proj',ed?(ed.project_id||''):(projId||''),'المشروع')}
  <div class="field"><label>البيان / ملاحظات <span class="muted mini">(اختياري، كتابة حرة)</span></label><textarea id="t_note" rows="2" placeholder="${isIn?'مثال: دفعة أولى من عقد مشروع…':'مثال: دفعة مقاول باطن، فاتورة رقم…'}">${esc(ed?(ed.note||''):'')}</textarea></div>
  ${cf?`<div class="grid g2">${cf}</div>`:''}
  <div class="field"><label>صورة الإيصال <span class="muted mini">(اختياري)</span></label><div class="toolbar"><button class="btn" onclick="pickAnyFile('t_file')">📎 اختيار</button><span id="t_file" class="muted mini">${ed&&ed.file_name?esc(ed.file_name):'لم يتم اختيار ملف'}</span></div></div>
  ${isIn?'':'<p class="muted mini">🔐 سند الصرف يتطلب كود المدير.</p>'}`,
  `<button class="btn primary" onclick="saveTreasury('${dir}','${id||''}')">${ed?'حفظ التعديل':'تسجيل السند'}</button><button class="btn" onclick="closeModal()">إلغاء</button>`);}
async function saveTreasury(dir,id){return withBusy(async()=>{
  const ed=id?S.treasury.find(t=>t.id===id):null;const amount=fn('t_amt');
  if(!(amount>0)){toast('أدخل مبلغاً صحيحاً','err');if(window.shakeField)shakeField('t_amt');return}
  const method0=fv('t_method')||'cash';let advEmp=null;
  /* سند صرف بنوع «سلفة» لموظف = سلفة حقيقية تُخصم من راتبه (تُسجَّل في ملفه وفي الرواتب) */
  if(dir==='out'&&!ed&&method0!=='cheque'&&/سلف/.test(fv('t_cat')||'')){advEmp=empById(fv('t_emp'))||activeEmps().find(e=>e.name&&e.name===(fv('t_party')||'').trim())||null;
    if(!advEmp){toast('سند السلفة: اختر الموظف من خانة «الموظف»','err');if(window.shakeField)shakeField('t_emp');return}}
  if(dir==='out'&&!await requirePin(ed?'تعديل سند صرف':'سند صرف'))return;
  const method=fv('t_method')||'cash';
  if(!ed&&method==='cheque'){/* شيك: يُسجَّل في الشيكات ويُقيَّد في الحساب عند التحصيل/الصرف */
    const c=await DB.upsert('cheques',{id:uid(),kind:dir,number:fv('t_chqno'),party:fv('t_party')||((empById(fv('t_emp'))||{}).name)||'',bank:fv('t_chqbank'),amount,currency:fv('t_cur'),issue_date:fv('t_date')||iso(today()),due_date:fv('t_chqdue')||null,account:isBankKey(fv('t_acct'))?fv('t_acct'):(bankAccts()[0]||{}).key||'bank',note:[fv('t_cat'),fv('t_note')].filter(Boolean).join(' — '),emp_id:fv('t_emp')||null,project_id:document.getElementById('t_proj')?(fv('t_proj')||null):null,ref_type:'voucher'});
    closeModal();toast(`سُجّل كشيك ${c.vno||''} — يُقيَّد في الحساب عند ${dir==='in'?'التحصيل':'الصرف'} من تبويب الشيكات`,'ok');render();return;}
  const f=await saveFilePending();const ex={};vfields(dir).forEach((fd,i)=>{const v=fv('vf_'+i);if(v!=='')ex[fd.label]=v;});ex['الطريقة']=method==='transfer'?'تحويل بنكي':'كاش';
  if(advEmp){const aid=uid(),d=fv('t_date')||iso(today()),cur=fv('t_cur')||'AED',why=fv('t_note')||'سلفة بسند صرف';
    await DB.upsert('advances',{id:aid,emp_id:advEmp.id,kind:'loan',amount,currency:cur,reason:why,request_date:d,status:'disbursed',approved_by:'المدير',approved_at:d,disbursed_at:d,remaining:amount,installments:1,installment_amount:amount,repay_method:'salary',first_month:null});
    await DB.upsert('treasury',{id:uid(),direction:'out',created_by:'admin',date:d,category:'صرف سلفة',amount,currency:cur,emp_id:advEmp.id,account:fv('t_acct')||'main',party:advEmp.name,ref_type:'advance',ref_id:aid,...(document.getElementById('t_proj')?{project_id:fv('t_proj')||null}:{}),note:why,extra:Object.keys(ex).length?JSON.stringify(ex):null,...f});
    await DB.upsert('notes',{id:uid(),emp_id:advEmp.id,date:d,kind:'ملاحظة',text:`صرف سلفة ${money(amount,cur)} بسند صرف — ${why}`});
    closeModal();toast(`تم صرف سلفة ${money(amount,cur)} لـ ${advEmp.name} — تُخصم من راتبه`,'ok');render();return;}
  const base=ed?{...ed}:{id:uid(),direction:dir,created_by:'admin'};
  await DB.upsert('treasury',{...base,date:fv('t_date')||iso(today()),category:fv('t_cat'),amount,currency:fv('t_cur'),emp_id:fv('t_emp')||null,account:fv('t_acct')||'main',party:fv('t_party')||null,...(document.getElementById('t_proj')?{project_id:fv('t_proj')||null}:{}),note:fv('t_note'),extra:Object.keys(ex).length?JSON.stringify(ex):null,...f});
  closeModal();toast(ed?'تم حفظ التعديل':'تم تسجيل السند','ok');render();});}
function openVoucherFieldsEditor(dir){vfDraft=vfields(dir).map(f=>({...f}));vfDir=dir;paintVfEditor();}
let vfDraft=[],vfDir='in';
function paintVfEditor(){openModal(`⚙️ تخصيص ${vfDir==='in'?'سند القبض':'سند الصرف'}`,`<p class="muted mini">أضف أي حقل تريده في السند (مثال: رقم العقد، اسم المشروع، رقم الفاتورة). تظهر الحقول في نموذج السند وفي الطباعة والتقارير. الحقول الأساسية (التاريخ، المبلغ، من/إلى، النوع، البيان) ثابتة.</p>
  <div id="vf_rows">${vfDraft.map((f,i)=>`<div class="frow3" style="align-items:end"><div class="field"><label>اسم الحقل</label><input value="${esc(f.label)}" oninput="vfDraft[${i}].label=this.value"></div><div class="field"><label>النوع</label><select onchange="vfDraft[${i}].type=this.value;paintVfEditor()"><option value="text" ${f.type==='text'?'selected':''}>نص</option><option value="number" ${f.type==='number'?'selected':''}>رقم</option><option value="date" ${f.type==='date'?'selected':''}>تاريخ</option><option value="list" ${f.type==='list'?'selected':''}>قائمة اختيار</option></select></div><div class="field">${f.type==='list'?`<label>الخيارات (بفاصلة)</label><input value="${esc((f.opts||[]).join('،'))}" oninput="vfDraft[${i}].opts=this.value.split(/[,،]/).map(x=>x.trim()).filter(Boolean)">`:'<label>&nbsp;</label>'}<button class="btn sm danger" onclick="vfDraft.splice(${i},1);paintVfEditor()">حذف الحقل</button></div></div>`).join('')||'<div class="empty">لا توجد حقول إضافية بعد</div>'}</div>
  <button class="btn" onclick="vfDraft.push({label:'',type:'text'});paintVfEditor()">＋ حقل جديد</button>`,
  `<button class="btn primary" onclick="saveVfEditor()">حفظ</button><button class="btn" onclick="closeModal()">إلغاء</button>`);}
async function saveVfEditor(){const clean=vfDraft.filter(f=>(f.label||'').trim()).map(f=>({label:f.label.trim().slice(0,60),type:f.type||'text',...(f.type==='list'?{opts:(f.opts||[]).slice(0,40)}:{})}));
  try{const cur={in:vfields('in'),out:vfields('out')};cur[vfDir]=clean;await DB.setSetting('voucherFields',cur);closeModal();toast('تم حفظ تخصيص السند','ok');render();}catch(e){toast('تخصيص السند يتطلب صلاحية المدير','err');}}
function printTreasuryVoucher(id){const t=S.treasury.find(x=>x.id===id);if(!t)return;const isIn=t.direction==='in',e=empById(t.emp_id);const ex=(()=>{try{return Object.entries(JSON.parse(t.extra||'{}'));}catch{return [];}})();
  api.printHTML(letterShell(`<h2 style="text-align:center;text-decoration:underline">${t.ref_type==='transfer'?'سند تحويل':isIn?'سند قبض':'سند صرف'}</h2><p style="text-align:left">رقم السند: <b dir="ltr">${esc(t.vno||'')}</b> &nbsp; التاريخ: ${fmtDate(t.date)}</p>
  <table style="width:100%;border-collapse:collapse;margin:10px 0" border="1" cellpadding="7"><tr><td style="width:22%"><b>${isIn?'استلمنا من':'صُرف إلى'}</b></td><td>${esc(partyOf(t)||'—')}</td><td style="width:18%"><b>الحساب</b></td><td>${esc(ACCOUNTS[acctOf(t)]||'')}</td></tr>
  <tr><td><b>المبلغ</b></td><td colspan="3" style="font-size:1.25em"><b>${money(t.amount,t.currency)}</b></td></tr><tr><td><b>نوع السند</b></td><td colspan="3">${esc(t.category||'')}${t.ref_type?` (${REF_LBL[t.ref_type]||''})`:''}</td></tr>
  ${e?`<tr><td><b>الموظف</b></td><td colspan="3">${esc(e.name)}</td></tr>`:''}${projName(t.project_id)?`<tr><td><b>المشروع</b></td><td colspan="3">${esc(projName(t.project_id))}</td></tr>`:''}<tr><td><b>البيان</b></td><td colspan="3">${esc(t.note||'')}</td></tr>${ex.map(([k,v])=>`<tr><td><b>${esc(k)}</b></td><td colspan="3">${esc(v)}</td></tr>`).join('')}</table>
  <div class="sig"><div>${isIn?'المُسلِّم':'المستلم'}:<br><br>____________________</div><div>أمين الخزينة:<br><br>____________________</div><div>المدير:<br><br>____________________</div></div>`));}
async function exportVouchers(dir){const rows=vRows(dir);const head=['رقم السند','التاريخ',dir==='in'?'من':'إلى','النوع','الحساب','العملة','المبلغ','البيان','بيانات إضافية'];
  const p=await api.exportCSV(`${dir==='in'?'سندات_القبض':'سندات_الصرف'}_${iso(today())}.csv`,csvOf(head,rows.map(t=>[t.vno||'',t.date,partyOf(t),t.category||'',ACCOUNTS[acctOf(t)]||'',t.currency||'AED',+t.amount||0,t.note||'',extraOf(t)])));if(p)toast('تم حفظ الملف: '+p,'ok');}
function printVoucherReport(dir){const rows=vRows(dir).slice().sort((a,b)=>a.date.localeCompare(b.date)||(a.vno||'').localeCompare(b.vno||''));const tot=rows.reduce((s,t)=>s+trAmt(t),0);
  api.printHTML(letterShell(`<h2 style="text-align:center">تقرير ${dir==='in'?'سندات القبض':'سندات الصرف'}</h2><p>${vFilter.from||vFilter.to?`الفترة: ${fmtDate(vFilter.from)||'—'} إلى ${fmtDate(vFilter.to)||'—'}`:'كل الفترات'} — ${rows.length} سند</p><table style="width:100%;border-collapse:collapse" border="1" cellpadding="5"><thead><tr><th>الرقم</th><th>التاريخ</th><th>${dir==='in'?'من':'إلى'}</th><th>النوع</th><th>الحساب</th><th>البيان</th><th>المبلغ</th></tr></thead><tbody>${rows.map(t=>`<tr><td dir="ltr">${esc(t.vno||'')}</td><td>${fmtDate(t.date)}</td><td>${esc(partyOf(t))}</td><td>${esc(t.category||'')}</td><td>${esc(ACCT_SHORT[acctOf(t)]||'')}</td><td>${esc(t.note||'')}</td><td style="text-align:left">${n2(trAmt(t))}</td></tr>`).join('')}</tbody><tfoot><tr><td colspan="6"><b>الإجمالي</b></td><td style="text-align:left"><b>${n2(tot)} د.إ</b></td></tr></tfoot></table>`,true));}

/* ---------- التحويلات ---------- */
function finTransfers(){const g={};S.treasury.filter(t=>t.ref_type==='transfer').forEach(t=>{(g[t.ref_id]=g[t.ref_id]||[]).push(t);});
  const list=Object.values(g).map(a=>({out:a.find(x=>x.direction==='out'),inn:a.find(x=>x.direction==='in'),any:a[0]})).sort((a,b)=>b.any.date.localeCompare(a.any.date)||(b.any.vno||'').localeCompare(a.any.vno||''));
  return `<div class="card tight" style="margin-top:16px"><div class="card-head"><h2>التحويلات بين الحسابات</h2><div class="toolbar"><button class="btn primary" onclick="openTransferForm()">＋ تحويل جديد</button></div></div>
  <div class="table-wrap">${list.length?`<table><thead><tr><th>الرقم</th><th>التاريخ</th><th>من</th><th>إلى</th><th class="num">المبلغ</th><th>ملاحظة</th><th></th></tr></thead><tbody>${list.map(x=>`<tr><td dir="ltr"><b>${esc(x.any.vno||'—')}</b></td><td>${fmtDate(x.any.date)}</td><td>${x.out?esc(ACCOUNTS[acctOf(x.out)]||''):'—'}</td><td>${x.inn?esc(ACCOUNTS[acctOf(x.inn)]||''):'—'}</td><td class="num"><b>${n2(x.any.amount)} د.إ</b></td><td class="mini">${esc((x.any.note||'').replace(/\s*\([^)]*←[^)]*\)\s*$/,''))}</td><td><button class="btn sm" onclick="delTransfer('${x.any.ref_id}')">✕</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">لا توجد تحويلات. التحويل ينقل المبلغ بين الخزينة والبنك دون أن يُحسب مصروفاً أو إيراداً.</div>'}</div></div>`;}
async function delTransfer(gid){const rows=S.treasury.filter(t=>t.ref_type==='transfer'&&t.ref_id===gid);if(!rows.length)return;if(!await confirmDel('حذف هذا التحويل؟ سيعود كل مبلغ لحسابه الأصلي.'))return;if(!await requirePin('حذف تحويل'))return;return withBusy(async()=>{for(const t of rows)await DB.remove('treasury',t.id);toast('تم حذف التحويل','ok');render();});}


/* ---------- الخزينة الفرعية: صرف عهدة مباشرة (تُسجَّل فوراً: لمن، متى، رقم تلقائي، قسم) ---------- */
function openCustodyIssueForm(empId){
  if(!activeEmps().length){toast('أضف موظفاً أولاً','err');return}
  openModal('🧰 صرف عهدة من الخزينة الفرعية',`<div class="frow3"><div class="field"><label>التاريخ</label><input type="date" id="cu_date" value="${iso(today())}"></div><div class="field"><label>الموظف صاحب العهدة *</label><select id="cu_emp">${activeEmps().map(e=>`<option value="${e.id}" ${e.id===empId?'selected':''}>${esc(e.name)}</option>`).join('')}</select></div><div class="field"><label>تُصرف من</label><select id="cu_acct">${Object.keys(ACCOUNTS).map(k=>`<option value="${k}" ${k==='sub'?'selected':''}>${acctIcon(k)} ${esc(ACCOUNTS[k])}</option>`).join('')}</select></div></div>
  <div class="field"><label>طريقة الصرف</label><select id="cu_method"><option value="cash">💵 كاش</option><option value="transfer">🏦 تحويل بنكي</option></select></div>
  <div class="frow3"><div class="field"><label>المبلغ *</label><input type="number" step="0.01" id="cu_amt" dir="ltr"></div><div class="field"><label>العملة</label><select id="cu_cur"><option>AED</option><option>USD</option></select></div><div class="field"><label>القسم / القائمة <span class="muted mini">(اختياري)</span></label>${selWithAdd('cu_section','custodySections')}</div></div>
  ${projField('cu_proj','','المشروع')}
  <div class="field"><label>البيان / ملاحظات <span class="muted mini">(اختياري)</span></label><textarea id="cu_note" rows="2" placeholder="مثال: شراء خامات لموقع…"></textarea></div>
  <p class="muted mini">رقم العهدة يُولَّد تلقائياً. تُسوّى لاحقاً بفواتير (من تبويب المصروفات) أو برد المتبقي، وتظهر في ملف الموظف وفي الخزينة. 🔐 تتطلب كود المدير.</p>`,
  `<button class="btn primary" onclick="saveCustodyIssue()">تسجيل وصرف</button><button class="btn" onclick="closeModal()">إلغاء</button>`);}
async function saveCustodyIssue(){return withBusy(async()=>{const amount=fn('cu_amt'),emp=fv('cu_emp');
  if(!(amount>0)){toast('أدخل مبلغاً صحيحاً','err');if(window.shakeField)shakeField('cu_amt');return}if(!emp){toast('اختر الموظف','err');return}
  if(!await requirePin('صرف عهدة'))return;
  const d=fv('cu_date')||iso(today()),aid=uid(),note=fv('cu_note')||'عهدة',cur_=fv('cu_cur');
  const a=await DB.upsert('advances',{id:aid,emp_id:emp,kind:'custody',amount,currency:cur_,reason:note,request_date:d,status:'disbursed',disbursed_at:d,remaining:null,installments:1,installment_amount:0,repay_method:'cash',first_month:monthKey(today()),section:fv('cu_section')||null,project_id:fv('cu_proj')||null});
  await DB.upsert('treasury',{id:uid(),date:d,direction:'out',category:'صرف عهدة مالية',amount,currency:cur_,emp_id:emp,account:fv('cu_acct')||'main',ref_type:'custody',ref_id:aid,project_id:fv('cu_proj')||null,note:`${note}${a&&a.vno?' ('+a.vno+')':''}`,party:(empById(emp)||{}).name||null,extra:JSON.stringify({'الطريقة':fv('cu_method')==='transfer'?'تحويل بنكي':'كاش'}),created_by:'admin'});
  closeModal();toast(`تم صرف العهدة${a&&a.vno?' — رقم '+a.vno:''}`,'ok');render();});}

/* ---------- الحسابات البنكية ---------- */
function bankInUse(k){return S.treasury.some(t=>t.account===k)||S.cheques.some(c=>c.account===k)||S.closings.some(c=>c.account===k);}
function finBanks(){const banks=bankAccts();const sel=bankSel&&ACCOUNTS[bankSel]?bankSel:'';
  const keys=sel?[sel]:Object.keys(ACCOUNTS).filter(isBankKey);
  const rows=S.treasury.filter(t=>keys.includes(acctOf(t))).sort((a,b)=>b.date.localeCompare(a.date)||(b.vno||'').localeCompare(a.vno||'')).slice(0,300);
  return `<div class="grid g3" style="margin:16px 0">${banks.map(b=>{const bal=treasuryBalance(null,b.key);return `<div class="tile ${bal<0?'danger':''} ${sel===b.key?'info':''}" style="cursor:pointer" onclick="bankSel='${sel===b.key?'':b.key}';render()"><div class="lbl">🏦 ${esc(b.name)}</div><div class="num" style="font-size:1.4rem">${n2(bal)} د.إ</div><div class="sub">${b.bank?esc(b.bank)+' · ':''}${b.iban?`<span dir="ltr">${esc(b.iban)}</span> · `:''}<a href="#" onclick="event.stopPropagation();openBankForm('${b.key}');return false">تعديل</a>${bankInUse(b.key)?'':` · <a href="#" onclick="event.stopPropagation();delBank('${b.key}');return false">حذف</a>`}</div></div>`;}).join('')}
  <div class="tile" style="cursor:pointer;display:flex;align-items:center;justify-content:center" onclick="openBankForm()"><b>＋ إضافة حساب بنكي</b></div></div>
  <div class="card tight"><div class="card-head"><h2>حركات ${sel?esc(ACCOUNTS[sel]):'كل الحسابات البنكية'}</h2><div class="toolbar"><button class="btn" onclick="openTreasuryForm('in')">⬇️ سند قبض</button><button class="btn" onclick="openTreasuryForm('out')">⬆️ سند صرف</button><button class="btn" onclick="openTransferForm()">🔁 تحويل</button></div></div>
  <div class="table-wrap">${rows.length?`<table><thead><tr><th>الرقم</th><th>التاريخ</th><th>الحساب</th><th>الطرف</th><th>النوع</th><th>البيان</th><th class="num">داخل</th><th class="num">خارج</th></tr></thead><tbody>${rows.map(t=>`<tr><td dir="ltr" class="mini">${esc(t.vno||'')}</td><td>${fmtDate(t.date)}</td><td class="mini">${esc(ACCT_SHORT[acctOf(t)]||'')}</td><td>${esc(partyOf(t))}</td><td class="mini">${esc(t.category||'')}</td><td class="mini">${esc(t.note||'')}</td><td class="num" style="color:var(--ok)">${t.direction==='in'?n2(t.amount):''}</td><td class="num" style="color:var(--neg)">${t.direction==='out'?n2(t.amount):''}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">لا توجد حركات على هذا الحساب بعد.</div>'}</div></div>`;}
function openBankForm(key){const b=key?bankAccts().find(x=>x.key===key):null;
  openModal(b?'تعديل حساب بنكي':'إضافة حساب بنكي',`<div class="field"><label>اسم الحساب *</label><input id="bk_name" value="${esc(b?b.name:'')}" placeholder="مثال: بنك الإمارات دبي الوطني — جاري"></div><div class="frow"><div class="field"><label>اسم البنك <span class="muted mini">(اختياري)</span></label><input id="bk_bank" value="${esc(b?(b.bank||''):'')}"></div><div class="field"><label>رقم IBAN <span class="muted mini">(اختياري)</span></label><input id="bk_iban" dir="ltr" value="${esc(b?(b.iban||''):'')}"></div></div><div class="field"><label>الرصيد الافتتاحي (د.إ)</label><input type="number" step="0.01" id="bk_open" dir="ltr" value="${b?(+b.opening||0):0}"></div>`,
  `<button class="btn primary" onclick="saveBank('${key||''}')">حفظ</button><button class="btn" onclick="closeModal()">إلغاء</button>`);}
async function saveBank(key){const name=fv('bk_name');if(!name){toast('اكتب اسم الحساب','err');return}
  const list=bankAccts().map(x=>({...x}));const rec={name:name.slice(0,80),bank:fv('bk_bank').slice(0,80),iban:fv('bk_iban').slice(0,40),opening:fn('bk_open')};
  if(key){const i=list.findIndex(x=>x.key===key);if(i>=0)list[i]={...list[i],...rec};}else list.push({key:'bk_'+uid().replace(/[^a-z0-9]/g,'').slice(0,12),...rec});
  try{await DB.setSetting('bankAccounts',list);rebuildAccounts();closeModal();toast('تم حفظ الحساب البنكي','ok');render();}catch(e){toast('إدارة الحسابات البنكية تتطلب صلاحية المدير','err');}}
async function delBank(key){if(bankInUse(key)){toast('لا يمكن حذف حساب عليه حركات','err');return}const list=bankAccts().filter(x=>x.key!==key);if(!list.length){toast('يجب أن يبقى حساب بنكي واحد على الأقل','err');return}if(!await confirmBox('حذف هذا الحساب البنكي؟'))return;
  try{await DB.setSetting('bankAccounts',list);rebuildAccounts();toast('تم الحذف','ok');render();}catch(e){toast('يتطلب صلاحية المدير','err');}}

/* ---------- الشيكات ---------- */
const chqIsOpen=c=>CHQ_OPEN.includes(c.status);
function chqOverdue(c){return chqIsOpen(c)&&c.due_date&&c.due_date<iso(today());}
function chqRows(){const f=chqFilter,q=(f.q||'').toLowerCase();
  const list=S.cheques.filter(c=>(f.st==='all'||(f.st==='open'?chqIsOpen(c):c.status===f.st))&&(!f.kind||c.kind===f.kind)&&(!q||[c.number,c.party,c.bank,c.note,c.due_note,c.vno].join(' ').toLowerCase().includes(q)));
  return list.sort((a,b)=>f.st==='open'?((a.due_date||'9999').localeCompare(b.due_date||'9999')):((b.issue_date||'').localeCompare(a.issue_date||'')));}
function finCheques(){const rows=chqRows();const open=S.cheques.filter(chqIsOpen);const recv=open.filter(c=>c.kind==='in').reduce((s,c)=>s+toAED(+c.amount,c.currency),0),iss=open.filter(c=>c.kind==='out').reduce((s,c)=>s+toAED(+c.amount,c.currency),0);
  const soon=open.filter(c=>c.due_date&&c.due_date<=iso(new Date(today().getTime()+7*86400000)));
  return `<div class="grid g3" style="margin:16px 0"><div class="tile ok"><div class="lbl">شيكات مستلمة لم تُحصَّل</div><div class="num" style="font-size:1.4rem">${n2(recv)} د.إ</div><div class="sub">${open.filter(c=>c.kind==='in').length} شيك</div></div><div class="tile warn"><div class="lbl">شيكات مُصدرة لم تُصرف</div><div class="num" style="font-size:1.4rem">${n2(iss)} د.إ</div><div class="sub">${open.filter(c=>c.kind==='out').length} شيك</div></div><div class="tile ${soon.length?'danger':''}"><div class="lbl">مستحقة خلال 7 أيام أو متأخرة</div><div class="num" style="font-size:1.4rem">${soon.length}</div><div class="sub">حسب موعد الصرف المسجّل</div></div></div>
  <div class="card tight"><div class="card-head"><div class="toolbar">${[['open','غير منتهية'],['held','محفوظة'],['deposited','مودعة'],['deferred','مؤجلة'],['cleared','محصّلة'],['bounced','مرتدة'],['cancelled','ملغاة'],['all','الكل']].map(([k,l])=>`<span class="chip ${chqFilter.st===k?'on':''}" onclick="chqFilter.st='${k}';render()">${l}</span>`).join('')}<select class="search" style="min-width:120px" onchange="chqFilter.kind=this.value;render()"><option value="">مستلمة ومُصدرة</option><option value="in" ${chqFilter.kind==='in'?'selected':''}>مستلمة (قبض)</option><option value="out" ${chqFilter.kind==='out'?'selected':''}>مُصدرة (صرف)</option></select><input class="search" placeholder="🔍 بحث…" value="${esc(chqFilter.q)}" oninput="chqFilter.q=this.value;render()"></div>
  <div class="toolbar"><button class="btn" onclick="exportCheques()">⬇️ تصدير Excel</button><button class="btn" onclick="printCheques()">🖨️ تقرير الشيكات</button><button class="btn primary" onclick="openChequeForm()">＋ شيك جديد</button></div></div>
  <div class="table-wrap">${rows.length?`<table><thead><tr><th>الرقم</th><th>النوع</th><th>الطرف</th><th>رقم الشيك / البنك</th><th class="num">المبلغ</th><th>الإصدار</th><th>موعد الصرف</th><th>الحالة</th><th></th></tr></thead><tbody>${rows.map(c=>{const st=CHQ_ST[c.status]||CHQ_ST.held;return `<tr><td dir="ltr" class="mini" style="white-space:nowrap"><b>${esc(c.vno||"—")}</b></td><td><span class="badge ${c.kind==='in'?'b-ok':'b-danger'}">${c.kind==='in'?'مستلم':'مُصدر'}</span></td><td><b>${esc(c.party||'—')}</b>${projBadge(c.project_id)}${c.note?`<div class="muted mini">${esc(c.note)}</div>`:''}</td><td class="mini"><span dir="ltr">${esc(c.number||'')}</span>${c.bank?`<div class="muted">${esc(c.bank)}</div>`:''}</td><td class="num"><b>${money(c.amount,c.currency)}</b></td><td>${fmtDate(c.issue_date)}</td><td>${c.due_date?fmtDate(c.due_date):'<span class="muted">—</span>'}${chqOverdue(c)?' <span class="badge b-danger">متأخر</span>':''}${c.due_note?`<div class="muted mini">${esc(c.due_note)}</div>`:''}</td><td><span class="badge ${st.cls}">${st.l}</span>${c.cleared_at?`<div class="muted mini">${fmtDate(c.cleared_at)}</div>`:''}</td><td style="white-space:nowrap">${chqActions(c)}</td></tr>`;}).join('')}</tbody></table>`:'<div class="empty">لا توجد شيكات بهذه الشروط. اضغط «شيك جديد» لتسجيل شيك مستلم أو مُصدر.</div>'}</div></div>
  <p class="muted mini" style="margin-top:8px">الشيك لا يدخل رصيد البنك إلا عند «تحصيل / صرف»، وعندها يتسجّل سند قبض أو صرف تلقائي في الحساب المختار ويظهر في الدفاتر والتقارير. موعد الصرف حر ويمكن تغييره أو تأجيله في أي وقت.</p>`;}
function chqActions(c){const b=(l,f,cls='')=>`<button class="btn sm ${cls}" onclick="${f}">${l}</button> `;
  if(c.status==='cleared')return b('↩️ تراجع',`unclearCheque('${c.id}')`)+b('🖨️',`printCheque('${c.id}')`);
  if(c.status==='bounced'||c.status==='cancelled')return b('إعادة فتح',`setChqStatus('${c.id}','held')`)+b('✏️',`openChequeForm('${c.id}')`);
  return b(c.kind==='in'?'✅ تحصيل':'✅ صرف',`clearCheque('${c.id}')`,'ok')+(c.kind==='in'&&c.status==='held'?b('إيداع',`setChqStatus('${c.id}','deposited')`):'')+b('⏳ تأجيل',`deferCheque('${c.id}')`)+b('مرتد',`setChqStatus('${c.id}','bounced')`)+b('إلغاء',`setChqStatus('${c.id}','cancelled')`)+b('✏️',`openChequeForm('${c.id}')`);}
function openChequeForm(id){const ed=id?S.cheques.find(c=>c.id===id):null;const lockAmt=!!(ed&&ed.status==='cleared');
  openModal(ed?'✏️ تعديل شيك':'شيك جديد',`<div class="frow3"><div class="field"><label>النوع *</label><select id="c_kind" ${lockAmt?'disabled':''}><option value="in" ${ed&&ed.kind==='in'?'selected':''}>شيك مستلم (قبض)</option><option value="out" ${ed&&ed.kind==='out'?'selected':''}>شيك مُصدر (صرف)</option></select></div><div class="field"><label>التاريخ</label><input type="date" id="c_date" value="${ed?(ed.issue_date||iso(today())):iso(today())}"></div><div class="field"><label>رقم الشيك <span class="muted mini">(اختياري)</span></label><input id="c_no" dir="ltr" value="${esc(ed?(ed.number||''):'')}"></div></div>
  <div class="frow"><div class="field"><label>اسم الطرف (من / إلى) <span class="muted mini">(اختياري)</span></label><input id="c_party" list="c_parties" value="${esc(ed?(ed.party||''):'')}"><datalist id="c_parties">${[...new Set([...S.cheques.map(c=>c.party),...S.treasury.map(t=>t.party)].filter(Boolean))].map(p=>`<option value="${esc(p)}">`).join('')}</datalist></div><div class="field"><label>اسم البنك <span class="muted mini">(اختياري)</span></label><input id="c_bank" value="${esc(ed?(ed.bank||''):'')}"></div></div>
  <div class="frow3"><div class="field"><label>المبلغ *</label><input type="number" step="0.01" id="c_amt" dir="ltr" value="${ed?ed.amount:''}" ${lockAmt?'readonly':''}></div><div class="field"><label>العملة</label><select id="c_cur" ${lockAmt?'disabled':''}><option ${ed&&ed.currency==='AED'?'selected':''}>AED</option><option ${ed&&ed.currency==='USD'?'selected':''}>USD</option></select></div><div class="field"><label>الحساب</label><select id="c_acct">${Object.keys(ACCOUNTS).map(k=>`<option value="${k}" ${(ed?ed.account:'bank')===k?'selected':''}>${esc(ACCOUNTS[k])}</option>`).join('')}</select></div></div>
  <div class="frow"><div class="field"><label>موعد الصرف <span class="muted mini">(اختياري)</span></label><input type="date" id="c_due" value="${ed?(ed.due_date||''):''}"></div><div class="field"><label>ملاحظة الموعد <span class="muted mini">(اختياري، كتابة حرة)</span></label><input id="c_duenote" value="${esc(ed?(ed.due_note||''):'')}" placeholder="مثال: يُصرف فوراً / مؤجل حتى نهاية الشهر"></div></div>
  ${projField('c_proj',ed?(ed.project_id||''):'','المشروع')}<div class="field"><label>ملاحظات <span class="muted mini">(اختياري)</span></label><textarea id="c_note" rows="2">${esc(ed?(ed.note||''):'')}</textarea></div>`,
  `<button class="btn primary" onclick="saveCheque('${id||''}')">${ed?'حفظ التعديل':'تسجيل الشيك'}</button><button class="btn" onclick="closeModal()">إلغاء</button>`);}
async function saveCheque(id){return withBusy(async()=>{const ed=id?S.cheques.find(c=>c.id===id):null;const lock=!!(ed&&ed.status==='cleared');const amount=lock?+ed.amount:fn('c_amt');
  if(!(amount>0)){toast('أدخل مبلغاً صحيحاً','err');if(window.shakeField)shakeField('c_amt');return}
  const rec={kind:lock?ed.kind:fv('c_kind'),number:fv('c_no'),party:fv('c_party'),bank:fv('c_bank'),amount,currency:lock?ed.currency:fv('c_cur'),issue_date:fv('c_date')||iso(today()),due_date:fv('c_due')||null,due_note:fv('c_duenote'),account:fv('c_acct')||'bank',note:fv('c_note'),...(document.getElementById('c_proj')?{project_id:fv('c_proj')||null}:{})};
  await DB.upsert('cheques',ed?{...ed,...rec}:{id:uid(),status:'held',...rec});closeModal();toast(ed?'تم حفظ التعديل':'تم تسجيل الشيك','ok');render();});}
async function setChqStatus(id,st){const c=S.cheques.find(x=>x.id===id);if(!c)return;await DB.upsert('cheques',{...c,status:st});toast('تم تحديث حالة الشيك','ok');render();}
async function deferCheque(id){const c=S.cheques.find(x=>x.id===id);if(!c)return;
  openModal('⏳ تأجيل الشيك',`<div class="field"><label>موعد الصرف الجديد <span class="muted mini">(اختياري)</span></label><input type="date" id="d_due" value="${c.due_date||''}"></div><div class="field"><label>ملاحظة <span class="muted mini">(اختياري)</span></label><input id="d_note" value="${esc(c.due_note||'')}" placeholder="مثال: بطلب العميل، يُصرف بعد 10 أيام"></div>`,`<button class="btn primary" onclick="saveDefer('${id}')">حفظ</button><button class="btn" onclick="closeModal()">إلغاء</button>`);}
async function saveDefer(id){const c=S.cheques.find(x=>x.id===id);if(!c)return;await DB.upsert('cheques',{...c,status:'deferred',due_date:fv('d_due')||null,due_note:fv('d_note')});closeModal();toast('تم تأجيل الشيك','ok');render();}
async function clearCheque(id){const c=S.cheques.find(x=>x.id===id);if(!c)return;const isIn=c.kind==='in';
  openModal(isIn?'✅ تحصيل الشيك':'✅ صرف الشيك',`<p class="muted">سيُسجَّل ${isIn?'سند قبض':'سند صرف'} تلقائياً بمبلغ <b>${money(c.amount,c.currency)}</b>${c.party?` — ${esc(c.party)}`:''}.</p><div class="frow"><div class="field"><label>تاريخ ${isIn?'التحصيل':'الصرف'}</label><input type="date" id="cl_date" value="${iso(today())}"></div><div class="field"><label>الحساب</label><select id="cl_acct">${Object.keys(ACCOUNTS).map(k=>`<option value="${k}" ${(c.account||'bank')===k?'selected':''}>${esc(ACCOUNTS[k])}</option>`).join('')}</select></div></div>${isIn?'':'<p class="muted mini">🔐 يتطلب كود المدير.</p>'}`,
  `<button class="btn primary" onclick="doClearCheque('${id}')">تأكيد</button><button class="btn" onclick="closeModal()">إلغاء</button>`);}
async function doClearCheque(id){return withBusy(async()=>{const c=S.cheques.find(x=>x.id===id);if(!c||c.status==='cleared')return;const isIn=c.kind==='in';if(!isIn&&!await requirePin('صرف شيك'))return;
  const d=fv('cl_date')||iso(today()),acct=fv('cl_acct')||'bank',tid=uid();
  await DB.upsert('treasury',{id:tid,date:d,direction:isIn?'in':'out',category:isIn?'تحصيل شيك':'صرف شيك',amount:+c.amount,currency:c.currency||'AED',account:acct,party:c.party||null,ref_type:'cheque',ref_id:c.id,cheque_id:c.id,project_id:c.project_id||null,note:`شيك ${c.number?'رقم '+c.number:''}${c.bank?' — '+c.bank:''} ${c.vno?'('+c.vno+')':''}`.trim(),created_by:'admin'});
  await DB.upsert('cheques',{...c,status:'cleared',cleared_at:d,treasury_id:tid,account:acct});closeModal();toast(isIn?'تم التحصيل وتسجيل سند القبض':'تم الصرف وتسجيل سند الصرف','ok');render();});}
async function unclearCheque(id){const c=S.cheques.find(x=>x.id===id);if(!c)return;if(!await confirmDel('التراجع عن التحصيل؟ سيُلغى السند المرتبط ويعود الشيك «محفوظ».'))return;if(!await requirePin('تراجع عن تحصيل شيك'))return;
  return withBusy(async()=>{for(const t of S.treasury.filter(x=>x.ref_type==='cheque'&&x.ref_id===c.id))await DB.remove('treasury',t.id);await DB.upsert('cheques',{...c,status:'held',cleared_at:null,treasury_id:null});toast('تم التراجع','ok');render();});}
function printCheque(id){const c=S.cheques.find(x=>x.id===id);if(!c)return;const t=S.treasury.find(x=>x.id===c.treasury_id);if(t)printTreasuryVoucher(t.id);}
async function exportCheques(){const rows=chqRows();const p=await api.exportCSV(`الشيكات_${iso(today())}.csv`,csvOf(['الرقم','النوع','الطرف','رقم الشيك','البنك','العملة','المبلغ','تاريخ الإصدار','موعد الصرف','ملاحظة الموعد','الحالة','تاريخ التحصيل','ملاحظات'],rows.map(c=>[c.vno||'',c.kind==='in'?'مستلم':'مُصدر',c.party||'',c.number||'',c.bank||'',c.currency||'AED',+c.amount||0,c.issue_date||'',c.due_date||'',c.due_note||'',(CHQ_ST[c.status]||{}).l||'',c.cleared_at||'',c.note||'']))); if(p)toast('تم حفظ الملف: '+p,'ok');}
function printCheques(){const rows=chqRows();const sum=k=>rows.filter(c=>c.kind===k).reduce((s,c)=>s+toAED(+c.amount,c.currency),0);
  api.printHTML(letterShell(`<h2 style="text-align:center">تقرير الشيكات</h2><p>${esc(({open:'غير المنتهية',all:'كل الحالات'})[chqFilter.st]||(CHQ_ST[chqFilter.st]||{}).l||'')} — ${rows.length} شيك — تاريخ التقرير: ${fmtDate(iso(today()))}</p><table style="width:100%;border-collapse:collapse" border="1" cellpadding="5"><thead><tr><th>الرقم</th><th>النوع</th><th>الطرف</th><th>رقم الشيك</th><th>البنك</th><th>المبلغ</th><th>موعد الصرف</th><th>الحالة</th><th>ملاحظات</th></tr></thead><tbody>${rows.map(c=>`<tr><td dir="ltr">${esc(c.vno||'')}</td><td>${c.kind==='in'?'مستلم':'مُصدر'}</td><td>${esc(c.party||'')}</td><td dir="ltr">${esc(c.number||'')}</td><td>${esc(c.bank||'')}</td><td style="text-align:left">${n2(c.amount)} ${cur(c.currency)}</td><td>${c.due_date?fmtDate(c.due_date):''} ${esc(c.due_note||'')}</td><td>${(CHQ_ST[c.status]||{}).l||''}</td><td>${esc(c.note||'')}</td></tr>`).join('')}</tbody></table><p><b>إجمالي المستلمة:</b> ${n2(sum('in'))} د.إ &nbsp; <b>إجمالي المُصدرة:</b> ${n2(sum('out'))} د.إ</p>`,true));}

/* ---------- تكامل مع الأجزاء القديمة ---------- */
(function(){
  const _fo=finOverview;finOverview=function(){const open=S.cheques.filter(chqIsOpen);const soon=open.filter(c=>c.due_date&&c.due_date<=iso(new Date(today().getTime()+7*86400000)));
    const strip=open.length?`<div class="banner ${soon.length?'warn':'info'}" style="margin-top:16px"><span>🧾 ${open.length} شيك غير منتهٍ${soon.length?` — منها <b>${soon.length}</b> مستحق خلال 7 أيام أو متأخر`:''}.</span><button class="btn sm" onclick="finTab='cheques';render()">فتح الشيكات</button></div>`:'';return strip+_fo();};
  const _ca=computeAlerts;computeAlerts=function(){const a=_ca();try{const td=iso(today());S.cheques.filter(chqIsOpen).forEach(c=>{if(!c.due_date)return;const du=daysUntil(c.due_date);if(du===null||du>3)return;a.push({kind:'chq',lvl:du<0?1:2,cls:du<0?'b-danger':'b-warn',emp:{id:'',name:'الشيكات'},txt:`شيك ${c.kind==='in'?'مستلم':'مُصدر'} ${c.number?'رقم '+c.number+' ':''}بمبلغ ${money(c.amount,c.currency)}${c.party?' — '+c.party:''} ${du<0?`متأخر ${-du} يوم`:du===0?'يستحق اليوم':`يستحق خلال ${du} يوم`}`,when:du,page:'finance'});});}catch(e){}a.sort((x,y)=>x.lvl-y.lvl||x.when-y.when);return a;};
  const _dt=delTreasury;delTreasury=async function(id){const t=S.treasury.find(x=>x.id===id);if(t&&t.ref_type==='cheque'){toast('هذا السند مرتبط بشيك — استخدم «تراجع» من قسم الشيكات','err');return}return _dt(id);};
})();

/* ---------- 5.5.0: حركة الصندوق الفرعي + التقرير الشامل ---------- */
function finSubLedger(){const rows=S.treasury.filter(t=>acctOf(t)==='sub').sort((a,b)=>b.date.localeCompare(a.date)||(b.created_at||'').localeCompare(a.created_at||''));const bal=treasuryBalance(null,'sub');
  return `<div class="card tight" style="margin-top:16px"><div class="card-head"><div><h2>🧰 الخزينة الفرعية — صندوق العُهد والسلف</h2><div class="muted mini">الرصيد الحالي <b>${n2(bal)} د.إ</b> · عُهد قائمة مع الموظفين ${n2(openCustodyTotal())} د.إ · رصيد افتتاحي ${n2(acctOpening('sub'))}</div></div><div class="toolbar"><button class="btn primary" onclick="feedSubTreasury()">⬇️ تغذية من الخزينة الرئيسية</button><button class="btn" onclick="openCustodyIssueForm()">🧰 صرف عهدة</button><button class="btn" onclick="finTab='loans';render()">🤝 السلف</button><button class="btn" onclick="setSubOpening()">⚙️ رصيد افتتاحي</button></div></div>
  <p class="muted mini" style="margin:0 14px 10px">الصندوق الفرعي صندوق حقيقي له رصيد: يتغذّى بتحويل من الخزينة الرئيسية، وتُصرف منه العُهد والسلف (ويمكن الصرف منه في أي سند أو مصروف باختياره كحساب). كل حركة هنا تظهر أيضاً في دفتر الخزينة وملف الموظف والمشروع.</p>
  <div class="table-wrap">${rows.length?`<table><thead><tr><th>التاريخ</th><th>الرقم</th><th>النوع</th><th>الطرف</th><th>البيان</th><th class="num">داخل</th><th class="num">خارج</th></tr></thead><tbody>${rows.map(t=>`<tr><td>${fmtDate(t.date)}</td><td dir="ltr" class="mini">${esc(t.vno||'')}</td><td><span class="badge ${t.direction==='in'?'b-ok':'b-danger'}">${esc(t.category||'')}</span></td><td>${esc(partyOf(t)||'—')}${projBadge(t.project_id)}</td><td class="mini">${esc(t.note||'')}</td><td class="num" style="color:var(--ok)">${t.direction==='in'?n2(trAmt(t)):''}</td><td class="num" style="color:var(--neg)">${t.direction==='out'?n2(trAmt(t)):''}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">لا حركات بعد. ابدأ بـ «تغذية من الخزينة الرئيسية» ثم اصرف العُهد منه.</div>'}</div></div>`;}
async function feedSubTreasury(){openTransferForm();setTimeout(()=>{const f=document.getElementById('tr_from'),t=document.getElementById('tr_to');if(f)f.value='main';if(t)t.value='sub';},30);}
async function setSubOpening(){const v=await promptBox('رصيد افتتاحي للخزينة الفرعية','المبلغ (د.إ) — يُستخدم مرة واحدة عند بدء العمل بالصندوق','number');if(v===null)return;await DB.setSetting('subOpeningBalance',+v||0);toast('تم الحفظ','ok');render();}
let consRange={from:iso(new Date(today().getFullYear(),today().getMonth(),1)),to:iso(today())};
function consolidatedData(from,to){
  const inR=t=>(!from||t.date>=from)&&(!to||t.date<=to);const T=S.treasury.filter(inR);
  const accts=Object.keys(ACCOUNTS).map(k=>{const before=treasuryBalance(from?iso(new Date(new Date(from).getTime()-86400000)):null,k);const rows=T.filter(t=>acctOf(t)===k);const i=rows.filter(t=>t.direction==='in').reduce((s,t)=>s+trAmt(t),0),o=rows.filter(t=>t.direction==='out').reduce((s,t)=>s+trAmt(t),0);return {k,name:ACCOUNTS[k],open:from?before:acctOpening(k),inn:i,out:o,close:(from?before:acctOpening(k))+i-o};});
  const sum=(f)=>T.filter(f).reduce((s,t)=>s+trAmt(t),0);
  const sec=[
    ['سندات قبض (إيرادات)',sum(t=>t.direction==='in'&&!t.ref_type),'in'],
    ['سندات صرف (مصروفات مباشرة)',sum(t=>t.direction==='out'&&!t.ref_type),'out'],
    ['مصروفات بفواتير',sum(t=>t.ref_type==='expense'),'out'],
    ['رواتب مصروفة',sum(t=>t.ref_type==='payment'),'out'],
    ['عُهد مصروفة',sum(t=>t.ref_type==='custody'),'out'],
    ['عُهد مردودة',sum(t=>t.ref_type==='custody_return'),'in'],
    ['سلف مصروفة',sum(t=>t.ref_type==='advance'),'out'],
    ['سلف مسدَّدة',sum(t=>t.ref_type==='repayment'),'in'],
    ['شيكات محصَّلة',sum(t=>t.ref_type==='cheque'&&t.direction==='in'),'in'],
    ['شيكات مصروفة',sum(t=>t.ref_type==='cheque'&&t.direction==='out'),'out'],
    ['فواتير محصَّلة',sum(t=>t.ref_type==='invoice'),'in'],
    ['تحويلات بين الحسابات',sum(t=>t.ref_type==='transfer'&&t.direction==='out'),'x']];
  const ho=S.handovers.filter(h=>inR(h));const cu=S.advances.filter(a=>a.kind==='custody'&&a.status==='disbursed');
  const pend=S.cheques.filter(c=>chqIsOpen(c));
  return {accts,sec,ho,cu,pend,totIn:T.filter(t=>t.direction==='in'&&t.ref_type!=='transfer').reduce((s,t)=>s+trAmt(t),0),totOut:T.filter(t=>t.direction==='out'&&t.ref_type!=='transfer').reduce((s,t)=>s+trAmt(t),0)};}
function finConsolidated(){const D=consolidatedData(consRange.from,consRange.to);
  return `<div class="card tight" style="margin-top:16px"><div class="card-head"><div class="toolbar"><h2 style="margin:0">🧾 التقرير الشامل للخزينة</h2><label class="muted mini">من</label><input type="date" class="search" style="min-width:140px" value="${consRange.from}" onchange="consRange.from=this.value;render()"><label class="muted mini">إلى</label><input type="date" class="search" style="min-width:140px" value="${consRange.to}" onchange="consRange.to=this.value;render()"></div><div class="toolbar"><button class="btn" onclick="exportConsolidated()">⬇️ Excel</button><button class="btn primary" onclick="printConsolidated()">🖨️ طباعة</button></div></div>
  <div class="grid g3" style="padding:0 14px"><div class="tile ok"><div class="lbl">إجمالي الداخل</div><div class="num" style="font-size:1.3rem">${n2(D.totIn)} د.إ</div></div><div class="tile warn"><div class="lbl">إجمالي الخارج</div><div class="num" style="font-size:1.3rem">${n2(D.totOut)} د.إ</div></div><div class="tile info"><div class="lbl">الصافي</div><div class="num" style="font-size:1.3rem">${n2(D.totIn-D.totOut)} د.إ</div></div></div>
  <h3 style="margin:14px 14px 6px">أرصدة الحسابات</h3><div class="table-wrap"><table><thead><tr><th>الحساب</th><th class="num">أول المدة</th><th class="num">داخل</th><th class="num">خارج</th><th class="num">آخر المدة</th></tr></thead><tbody>${D.accts.map(a=>`<tr><td>${acctIcon(a.k)} <b>${esc(a.name)}</b></td><td class="num">${n2(a.open)}</td><td class="num" style="color:var(--ok)">${n2(a.inn)}</td><td class="num" style="color:var(--neg)">${n2(a.out)}</td><td class="num"><b>${n2(a.close)}</b></td></tr>`).join('')}</tbody></table></div>
  <h3 style="margin:14px 14px 6px">ما دخل وما خرج حسب النوع</h3><div class="table-wrap"><table><tbody>${D.sec.map(([l,v,d])=>`<tr><td>${esc(l)}</td><td class="num" style="color:${d==='in'?'var(--ok)':d==='out'?'var(--neg)':'inherit'}"><b>${n2(v)} د.إ</b></td></tr>`).join('')}</tbody></table></div>
  <div class="grid g2" style="padding:0 14px;margin-top:14px"><div><h3>عُهد قائمة مع الموظفين (${D.cu.length})</h3>${D.cu.length?`<table><tbody>${D.cu.map(a=>`<tr><td>${esc((empById(a.emp_id)||{}).name||'—')}</td><td class="num">${money(advRemaining(a),a.currency)}</td></tr>`).join('')}</tbody></table>`:'<p class="muted mini">لا يوجد</p>'}</div>
  <div><h3>محاضر تسليم وتسلم في المدة (${D.ho.length})</h3>${D.ho.length?`<table><tbody>${D.ho.map(h=>`<tr><td>${fmtDate(h.date)}</td><td>${esc(hoName(h,'from'))} ← ${esc(hoName(h,'to'))}</td><td class="num">${h.subject==='items'?esc((h.items||'').slice(0,40)):n2(h.counted)+' د.إ'}</td></tr>`).join('')}</tbody></table>`:'<p class="muted mini">لا يوجد</p>'}</div></div>
  ${D.pend.length?`<p class="muted mini" style="margin:12px 14px">🧾 شيكات لم تُنفَّذ بعد: ${D.pend.length} (لا تدخل في الأرصدة حتى تُحصَّل/تُصرف).</p>`:''}</div>`;}
function consolidatedHTML(){const D=consolidatedData(consRange.from,consRange.to);const tb=(h,rows)=>`<table border="1" cellpadding="5" style="border-collapse:collapse;width:100%;margin:6px 0 12px"><thead><tr>${h.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
  return `<h2 style="text-align:center">التقرير الشامل للخزينة</h2><p>المدة: <b>${fmtDate(consRange.from)}</b> إلى <b>${fmtDate(consRange.to)}</b> — إجمالي الداخل <b>${n2(D.totIn)}</b> · الخارج <b>${n2(D.totOut)}</b> · الصافي <b>${n2(D.totIn-D.totOut)} د.إ</b></p>
  <h3>أرصدة الحسابات</h3>${tb(['الحساب','أول المدة','داخل','خارج','آخر المدة'],D.accts.map(a=>[esc(a.name),n2(a.open),n2(a.inn),n2(a.out),'<b>'+n2(a.close)+'</b>']))}
  <h3>حسب النوع</h3>${tb(['البند','المبلغ (د.إ)'],D.sec.map(([l,v])=>[esc(l),n2(v)]))}
  <h3>عُهد قائمة</h3>${D.cu.length?tb(['الموظف','المتبقي'],D.cu.map(a=>[esc((empById(a.emp_id)||{}).name||''),money(advRemaining(a),a.currency)])):'<p>لا يوجد</p>'}
  <h3>محاضر التسليم والتسلم</h3>${D.ho.length?tb(['التاريخ','المُسلِّم','المُستلِم','الموضوع'],D.ho.map(h=>[fmtDate(h.date),esc(hoName(h,'from')),esc(hoName(h,'to')),h.subject==='items'?esc(h.items||''):n2(h.counted)+' د.إ'])):'<p>لا يوجد</p>'}`;}
function printConsolidated(){api.printHTML(letterShell(consolidatedHTML(),true));}
async function exportConsolidated(){const D=consolidatedData(consRange.from,consRange.to);const rows=[...D.accts.map(a=>['حساب',a.name,a.open,a.inn,a.out,a.close]),...D.sec.map(([l,v])=>['بند',l,'','','',v])];const f=await api.exportCSV(`التقرير_الشامل_${consRange.from}_${consRange.to}.csv`,csvOf(['النوع','البيان','أول المدة','داخل','خارج','آخر المدة/المبلغ'],rows));if(f)toast('تم حفظ الملف: '+f,'ok');}
